class Solution {
public:
    vector<string> generateParenthesis(int n) {
        vector<string> result;
        string cur;
        backtrack(n, 0, 0, cur, result);
        return result;
    }
private:
    void backtrack(int n, int open, int close, string& cur, vector<string>& result) {
        if (cur.size() == 2 * n) {
            result.push_back(cur);
            return;
        }
        if (open < n) {
            cur.push_back('(');
            backtrack(n, open + 1, close, cur, result);
            cur.pop_back();
        }
        if (close < open) {
            cur.push_back(')');
            backtrack(n, open, close + 1, cur, result);
            cur.pop_back();
        }
    }
};
